CREATE POLICY deeptrace_evidence_read ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'deeptrace-evidence' AND (storage.foldername(name))[1] IS NOT NULL AND (storage.foldername(name))[2] IS NOT NULL AND EXISTS (SELECT 1 FROM public.cases c WHERE c.id = (storage.foldername(name))[2]::uuid AND c.organization_id = (storage.foldername(name))[1]::uuid AND public.can_access_case(auth.uid(), c.id)));
CREATE POLICY deeptrace_evidence_upload ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'deeptrace-evidence' AND (storage.foldername(name))[1] IS NOT NULL AND (storage.foldername(name))[2] IS NOT NULL AND EXISTS (SELECT 1 FROM public.cases c WHERE c.id = (storage.foldername(name))[2]::uuid AND c.organization_id = (storage.foldername(name))[1]::uuid AND public.can_access_case(auth.uid(), c.id) AND public.has_org_role(auth.uid(), c.organization_id, ARRAY['admin','lead_analyst','analyst']::public.app_role[])));
CREATE POLICY deeptrace_evidence_update ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'deeptrace-evidence' AND (storage.foldername(name))[1] IS NOT NULL AND (storage.foldername(name))[2] IS NOT NULL AND EXISTS (SELECT 1 FROM public.cases c WHERE c.id = (storage.foldername(name))[2]::uuid AND c.organization_id = (storage.foldername(name))[1]::uuid AND public.can_access_case(auth.uid(), c.id) AND public.has_org_role(auth.uid(), c.organization_id, ARRAY['admin','lead_analyst','analyst']::public.app_role[]))) WITH CHECK (bucket_id = 'deeptrace-evidence' AND (storage.foldername(name))[1] IS NOT NULL AND (storage.foldername(name))[2] IS NOT NULL AND EXISTS (SELECT 1 FROM public.cases c WHERE c.id = (storage.foldername(name))[2]::uuid AND c.organization_id = (storage.foldername(name))[1]::uuid AND public.can_access_case(auth.uid(), c.id) AND public.has_org_role(auth.uid(), c.organization_id, ARRAY['admin','lead_analyst','analyst']::public.app_role[])));
CREATE POLICY deeptrace_evidence_delete ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'deeptrace-evidence' AND (storage.foldername(name))[1] IS NOT NULL AND (storage.foldername(name))[2] IS NOT NULL AND EXISTS (SELECT 1 FROM public.cases c WHERE c.id = (storage.foldername(name))[2]::uuid AND c.organization_id = (storage.foldername(name))[1]::uuid AND public.can_access_case(auth.uid(), c.id) AND public.has_org_role(auth.uid(), c.organization_id, ARRAY['admin','lead_analyst']::public.app_role[])));